const file = $input.first().json;
const pin = $('02 · Pin Alpha main').first().json;
const sel = $('01 · Select candidate').first().json;
const sourceCommit = pin.sha;
const candidatePath = sel.candidate_path;
const base = {
  origin: 'manual',
  source_commit: sourceCommit,
  candidate_path: candidatePath,
  source_ref: 'HCH725/alpha-strategy-research@' + sourceCommit + '/' + candidatePath,
  source_blob_sha: file.sha || null,
  qlib_run_id: null,
  run_state: 'NOT_SUBMITTED'
};
const readField = (fm, k) => {
  const m = fm.match(new RegExp('^' + k + ':\\s*(.*?)\\s*$', 'm'));
  return m ? m[1].trim().replace(/^["']|["']$/g, '') : null;
};
if (file.type !== 'file' || typeof file.content !== 'string')
  return [{ json: { ...base, route: 'NEEDS_REVIEW', reason: 'GitHub record content is not readable' } }];
let record;
try {
  record = Buffer.from(file.content.replace(/\s/g, ''), 'base64').toString('utf8');
} catch {
  return [{ json: { ...base, route: 'NEEDS_REVIEW', reason: 'GitHub record content is not decodable' } }];
}
if (!record.startsWith('---\n'))
  return [{ json: { ...base, route: 'NEEDS_REVIEW', reason: 'GitHub record has no readable YAML frontmatter' } }];
const end = record.indexOf('\n---', 4);
if (end < 0)
  return [{ json: { ...base, route: 'NEEDS_REVIEW', reason: 'Unterminated YAML frontmatter' } }];
const fm = record.slice(4, end);
const schema = readField(fm, 'schema');
const hb = readField(fm, 'hb_ready_status');
const impl = readField(fm, 'implementation_status');
// ponytail: admission checks schema + HB_READY PASS only. implementation_status stays informational.
if (schema !== 'strategy-research-record-v1' || hb !== 'PASS')
  return [{ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'NEEDS_REVIEW', reason: 'Invalid schema or HB_READY not PASS' } }];
// A. Market data is not ready for this run.
const fmData = readField(fm, 'market_data_ready') || readField(fm, 'data_ready');
const dataFalse = (v) => v === false || v === 'false' || v === 'no' || v === '0';
if (dataFalse(sel.market_data_ready) || dataFalse(fmData))
  return [{ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'WAITING_DATA', reason: 'Market data is not ready for this run', market_data_ready: false } }];
// B. Load the per-run executable handoff. It lives in this run input only.
const loadHandoff = (v) => {
  if (v == null || v === '') return null;
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  if (typeof v === 'string') {
    try {
      const o = JSON.parse(v);
      return (o && typeof o === 'object' && !Array.isArray(o)) ? o : null;
    } catch { return null; }
  }
  return null;
};
let handoff = loadHandoff(sel.executable_handoff);
let refOnly = false;
if (!handoff && typeof sel.handoff_ref === 'string' && sel.handoff_ref.trim() !== '') {
  handoff = loadHandoff(sel.handoff_ref.trim());
  if (!handoff) refOnly = true;
}
if (!handoff)
  return [{ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'IMPLEMENTATION_NEEDED', reason: refOnly ? 'IMPLEMENTATION_NEEDED: admitted strategy lacks executable materialization for this run (handoff_ref pointer only, no materialized handoff content)' : 'IMPLEMENTATION_NEEDED: admitted strategy lacks executable materialization for this run', market_data_ready: null } }];
// C. Verify frozen identity, refs, and hashes.
const isHex = (v, n) => typeof v === 'string' && new RegExp('^[a-f0-9]{' + n + '}$').test(v);
const isAbsPath = (v) => typeof v === 'string' && /^\/[A-Za-z0-9_@+./-]{1,511}$/.test(v) && !v.includes('..');
const bad = (d) => ({ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'NEEDS_REVIEW', reason: 'Handoff identity check failed: ' + d } });
if (handoff.source_commit !== sourceCommit) return [bad('source_commit does not match pinned Alpha main')];
if (handoff.candidate_path !== candidatePath) return [bad('candidate_path does not match selected candidate')];
if (handoff.source_blob_sha !== file.sha) return [bad('source_blob_sha does not match pinned blob')];
if (!isAbsPath(handoff.entrypoint_ref) || !isHex(handoff.entrypoint_sha256, 64)) return [bad('entrypoint ref or hash is invalid')];
if (!isAbsPath(handoff.effective_config_ref) || !isHex(handoff.effective_config_sha256, 64)) return [bad('effective_config ref or hash is invalid')];
if (!isHex(handoff.qlib_runtime_commit, 40)) return [bad('qlib_runtime_commit is invalid')];
if (handoff.research_cost_model == null && handoff.run_inputs == null) return [bad('declared cost or run inputs are missing')];
if (!handoff.evidence_refs || typeof handoff.evidence_refs !== 'object' || Array.isArray(handoff.evidence_refs) || Object.keys(handoff.evidence_refs).length === 0) return [bad('evidence refs are missing')];
// D/E. Capability check passes only on verified primitives.
const VERIFIED = {
  execution: ['qlib-native-backtest'],
  data: ['btcusdt-1h'],
  timing: ['bar-close-1h']
};
const gap = [];
const bucketed = (handoff.capabilities && typeof handoff.capabilities === 'object' && !Array.isArray(handoff.capabilities)) ? handoff.capabilities : null;
let declaredCount = 0;
if (bucketed) {
  for (const k of Object.keys(VERIFIED)) {
    const v = bucketed[k];
    const vals = Array.isArray(v) ? v : (typeof v === 'string' ? [v] : []);
    for (const x of vals) {
      if (typeof x !== 'string') { gap.push(k + ':non-string'); continue; }
      declaredCount += 1;
      if (!VERIFIED[k].includes(x)) gap.push(k + ':' + x);
    }
  }
  for (const k of Object.keys(bucketed)) {
    if (!(k in VERIFIED)) {
      const v = bucketed[k];
      const vals = Array.isArray(v) ? v : [v];
      for (const x of vals) { declaredCount += 1; gap.push(k + ':' + String(x)); }
    }
  }
}
if (Array.isArray(handoff.capability_declaration)) {
  for (const c of handoff.capability_declaration) {
    if (typeof c !== 'string' || c.indexOf(':') < 0) { gap.push('malformed:' + String(c)); continue; }
    const i = c.indexOf(':');
    const bucket = c.slice(0, i);
    const val = c.slice(i + 1);
    declaredCount += 1;
    if (!(bucket in VERIFIED) || !VERIFIED[bucket].includes(val)) gap.push(c);
  }
}
if (declaredCount === 0) return [bad('capability declaration is missing')];
if (gap.length > 0)
  return [{ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'ENGINEERING_HOLD', reason: 'New unverified capability: ' + gap.join(', '), capability_gap: gap, executable_handoff: handoff } }];
const transport_payload_b64 = Buffer.from(JSON.stringify(handoff), 'utf8').toString('base64');
return [{ json: { ...base, schema, hb_ready_status: hb, implementation_status: impl, route: 'READY', reason: 'HB_READY admission with verified executable handoff and verified capabilities', market_data_ready: true, executable_handoff: handoff, capability_gap: [], transport_payload_b64 } }];

const ssh = $input.first().json;
const upstream = $('03 · Engineering readiness').first().json;
if (upstream.route !== 'READY') throw new Error('Node04 HOLD: upstream is not READY');
const h = upstream.executable_handoff;
if (!h || typeof h !== 'object' || Array.isArray(h)) throw new Error('Node04 HOLD: validated executable handoff is missing');
if (ssh.code !== 0) throw new Error('Node04 SSH command failed');
let receipt;
try { receipt = JSON.parse(String(ssh.stdout || '').trim()); } catch { throw new Error('Node04 receipt is not JSON'); }
if (!receipt || typeof receipt !== 'object' || Array.isArray(receipt) || receipt.node04 !== 'PASS') throw new Error('Node04 receipt is not PASS');
if (receipt.candidate_blob_sha !== upstream.source_blob_sha) throw new Error('Node04 candidate identity mismatch');
if (receipt.candidate_blob_sha !== h.source_blob_sha) throw new Error('Node04 handoff identity mismatch');
if (receipt.entrypoint_sha256 !== h.entrypoint_sha256) throw new Error('Node04 entrypoint binding mismatch');
if (receipt.effective_config_sha256 !== h.effective_config_sha256) throw new Error('Node04 effective_config binding mismatch');
if (!/^[a-f0-9]{32}$/.test(String(receipt.run_id || ''))) throw new Error('Node04 run_id is missing or invalid');
return [{ json: { ...upstream, qlib_run_id: receipt.run_id, run_state: 'FINISHED', node04_receipt: receipt } }];

const ssh = $input.first().json;
const upstream = $('04 · Verify submit receipt').first().json;
const h = upstream.executable_handoff;
if (!h || typeof h !== 'object' || Array.isArray(h)) throw new Error('Node05 HOLD: validated executable handoff is missing');
if (ssh.code !== 0) throw new Error('Node05 HOLD: SSH command failed');
let receipt;
try { receipt = JSON.parse(String(ssh.stdout || '').trim()); } catch { throw new Error('Node05 HOLD: receipt is not JSON'); }
if (!receipt || typeof receipt !== 'object' || Array.isArray(receipt) || receipt.node05 !== 'PASS') throw new Error('Node05 HOLD: receipt is not PASS');
if (!/^[a-f0-9]{32}$/.test(String(receipt.run_id || '')) || receipt.run_id !== upstream.qlib_run_id) throw new Error('Node05 HOLD: run identity mismatch');
if (receipt.candidate_path !== upstream.candidate_path || receipt.candidate_blob_sha !== upstream.source_blob_sha) throw new Error('Node05 HOLD: candidate identity mismatch');
if (receipt.status !== 'FINISHED' || upstream.run_state !== 'FINISHED') throw new Error('Node05 HOLD: run is not FINISHED');
for (const key of ['params_count', 'metrics_count', 'artifacts_count'])
  if (!Number.isSafeInteger(receipt[key]) || receipt[key] <= 0) throw new Error('Node05 HOLD: missing or empty ' + key);
// ponytail: bind the readback to the Node04 receipt. No fixed paths live here.
const submitted = upstream.node04_receipt || {};
if (typeof receipt.out_dir !== 'string' || receipt.out_dir !== submitted.out_dir) throw new Error('Node05 HOLD: run location does not match submit receipt');
if (typeof receipt.experiment_id !== 'string' || !/^[0-9]+$/.test(receipt.experiment_id)) throw new Error('Node05 HOLD: experiment reference is invalid');
if (typeof submitted.experiment_id !== 'string' || receipt.experiment_id !== submitted.experiment_id) throw new Error('Node05 HOLD: experiment identity mismatch');
const runRef = receipt.out_dir + '/mlruns/' + receipt.experiment_id + '/' + receipt.run_id;
if (!receipt.refs || receipt.refs.mlflow_run !== runRef) throw new Error('Node05 HOLD: run reference mismatch');
if (receipt.refs.candidate !== 'https://api.github.com/repos/HCH725/alpha-strategy-research/git/blobs/' + upstream.source_blob_sha) throw new Error('Node05 HOLD: candidate reference mismatch');
if (h.evidence_refs && typeof h.evidence_refs === 'object' && !Array.isArray(h.evidence_refs)) {
  for (const [key, ref] of Object.entries(h.evidence_refs)) {
    if (key === 'candidate') continue;
    if (!receipt.refs || receipt.refs[key] !== ref) throw new Error('Node05 HOLD: evidence reference mismatch ' + key);
  }
}
for (const key of ['candidate', 'data', 'execution', 'runtime', 'evidence'])
  if (!receipt.readable || receipt.readable[key] !== true) throw new Error('Node05 HOLD: unreadable ' + key + ' evidence');
if (receipt.manifest_verified !== true || receipt.manifest_readback_run_id !== upstream.qlib_run_id ||
  typeof receipt.manifest_sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(receipt.manifest_sha256)) throw new Error('Node05 HOLD: manifest or run identity mismatch');
// Derive claimability from run facts. A single proof stays false through coverage_complete=false.
const coverageComplete = receipt.coverage_complete === true;
const evidenceComplete = receipt.manifest_verified === true;
const costDeclared = h.research_cost_model != null || h.run_inputs != null;
const derived = coverageComplete && evidenceComplete && costDeclared;
if (receipt.performance_claimable !== derived) throw new Error('Node05 HOLD: performance_claimable is not derived');
return [{ json: { ...upstream, performance_claimable: derived, node05_receipt: receipt } }];

// Node05 -> Node06 gate. It accepts the campaign-level IS_READY contract only.
// A representative single-cell receipt stays false (coverage_complete=false,
// performance_claimable=false) and holds here. No LLM and no MoA run here.
const x = $input.first().json;
const s = x.node05_receipt || {};
const h = x.executable_handoff || {};
const hold = (reason) => [{ json: {
  payload_kind: 'is_ready_hold', stage: '05b', route: 'HOLD', reason: reason,
  run_key: x.qlib_run_id || null, candidate_path: x.candidate_path || null
} }];
// An OOS round re-enters the same 04/05 path. It is handled by the OOS lane,
// never by this IS lane.
if ($('10 · OOS re-entry (04/05 contract)').isExecuted) { return []; }
if (x.run_state !== 'FINISHED') { return hold('run_not_finished'); }
if (x.performance_claimable !== true) { return hold('performance_not_claimable'); }
if (s.coverage_complete !== true) { return hold('coverage_incomplete'); }
if (s.manifest_verified !== true || !/^[a-f0-9]{64}$/.test(String(s.manifest_sha256 || ''))) { return hold('evidence_incomplete'); }
const runId = String(x.qlib_run_id || '');
if (!/^[a-f0-9]{32}$/.test(runId) || s.run_id !== runId || s.manifest_readback_run_id !== runId) { return hold('identity_incomplete'); }
if (!h || typeof h !== 'object' || Array.isArray(h)) { return hold('handoff_missing'); }
if (h.source_blob_sha !== x.source_blob_sha || h.candidate_path !== x.candidate_path) { return hold('handoff_identity_mismatch'); }
if (String(s.candidate_blob_sha) !== String(x.source_blob_sha)) { return hold('candidate_identity_mismatch'); }
if (h.research_cost_model == null && h.run_inputs == null) { return hold('cost_not_declared'); }
const refs = (s.refs && typeof s.refs === 'object' && !Array.isArray(s.refs)) ? s.refs : {};
if (typeof refs.mlflow_run !== 'string' || refs.mlflow_run.length === 0) { return hold('evidence_refs_missing'); }
// The retest lane re-enters through 09 with its own round contract.
const reentry = $('09 · RETEST re-entry (04 contract)');
let round = null;
if (reentry.isExecuted) {
  round = (reentry.first().json || {}).round_contract || null;
  if (!round || typeof round !== 'object' || Array.isArray(round)) { return hold('retest_round_contract_missing'); }
}
const completed = round
  ? (Array.isArray(round.completed_runs) ? round.completed_runs.slice() : null)
  : [];
if (round && completed === null) { return hold('retest_round_series_missing'); }
const roundIndex = round ? round.round_index : 0;
if (round) {
  if (!Number.isSafeInteger(roundIndex) || roundIndex !== completed.length || roundIndex > 3) { return hold('retest_round_index_invalid'); }
  const head = completed.length > 0 ? completed[completed.length - 1] : null;
  if (!head || head.run_key !== round.parent_run_key) { return hold('retest_parent_not_canonical_head'); }
  // The round only exists if its own handoff was materialised.
  if (!/^[a-f0-9]{64}$/.test(String(h.effective_config_sha256 || ''))) { return hold('retest_config_missing'); }
  if (h.effective_config_sha256 === round.parent_effective_config_sha256) { return hold('retest_config_not_materialised'); }
}
const rounds = completed.concat([{ round_index: roundIndex, run_key: runId, status: 'IS_SUCCESS' }]);
const isReady = {
  payload_kind: 'is_ready',
  run_key: runId,
  run_id: runId,
  round_index: roundIndex,
  period_basis: 'IS',
  metrics_summary: { params_count: s.params_count, metrics_count: s.metrics_count, artifacts_count: s.artifacts_count },
  metrics_ref: refs.mlflow_run,
  evidence_refs: (h.evidence_refs && typeof h.evidence_refs === 'object' && !Array.isArray(h.evidence_refs))
    ? h.evidence_refs
    : { run_manifest: String(refs.manifest || ''), metrics: refs.mlflow_run },
  applied_change_set: round ? round.change_set : null,
  prior_hypothesis_ref: round ? round.prior_hypothesis_ref : null,
  // ponytail: the allowlist is the handoff's declared allowlist. An undeclared
  // allowlist is empty, so Node08 forbids every override instead of guessing.
  allowed_override_params: Array.isArray(h.allowed_override_params) ? h.allowed_override_params : [],
  completed_runs: rounds,
  wiki_state: [],
  route: 'IS_READY'
};
return [{ json: isReady }];

// Reads the single Hermes turn. It does not reason: it only parses the result
// event of the stream-json output and validates its shape.
const ssh = $input.first().json;
const taskRef = $('06 · Hermes task payload');
const task = taskRef.first() ? taskRef.first().json : {};
const stop = (reason) => [{ json: Object.assign({}, task, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (!taskRef.isExecuted || task.payload_kind !== 'hermes_task') { return stop('hermes_task_payload_missing'); }
if (ssh.code !== 0) { return stop('hermes_exit_' + ssh.code); }
let result = null;
for (const line of String(ssh.stdout || '').split('\n')) {
  const text = line.trim();
  if (!text || text.charAt(0) !== '{') { continue; }
  let event = null;
  try { event = JSON.parse(text); } catch (error) { continue; }
  if (event && event.type === 'result' && typeof event.text === 'string') { result = event; }
}
if (result === null) { return stop('hermes_result_event_missing'); }
if (Number(result.exit_code) !== 0) { return stop('hermes_exit_' + result.exit_code); }
let raw = String(result.text).trim();
if (raw.slice(0, 3) === '```') { raw = raw.replace(/^```[a-zA-Z]*\n/, '').replace(/\n?```$/, '').trim(); }
let reply = null;
try { reply = JSON.parse(raw); } catch (error) { reply = null; }
if (reply === null || typeof reply !== 'object' || Array.isArray(reply)) { return stop('hermes_reply_not_json'); }
const analysis = reply.analysis;
if (analysis === null || typeof analysis !== 'object' || Array.isArray(analysis)) { return stop('hermes_format_error'); }
const out = Object.assign({}, task, { analysis: analysis, route: 'ANALYSIS_PENDING' });
if (reply.wiki_ack && typeof reply.wiki_ack === 'object' && !Array.isArray(reply.wiki_ack)) { out.wiki_ack = reply.wiki_ack; }
return [{ json: out }];

// Check the Node06 analysis contract. No LLM runs here.
const x = $input.first().json;
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
const a = x.analysis;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
const isText = (v) => typeof v === 'string' && v.length > 0;
const isHash = (v) => typeof v === 'string' && /^[a-f0-9]{64}$/.test(v);
const missing = [];
if (!isText(a.analysis_ref)) { missing.push('analysis_ref'); }
if (!isHash(a.analysis_hash)) { missing.push('analysis_hash'); }
if (!isText(a.source_run_key)) { missing.push('source_run_key'); }
if (!isText(a.source_run_id)) { missing.push('source_run_id'); }
if (!Array.isArray(a.lessons) || a.lessons.length === 0) { missing.push('lessons'); }
if (!Array.isArray(a.expectation_vs_actual) || a.expectation_vs_actual.length === 0) { missing.push('expectation_vs_actual'); }
if (typeof a.worth_retesting !== 'boolean') { missing.push('worth_retesting'); }
if (!a.proposal || typeof a.proposal !== 'object' || Array.isArray(a.proposal)) { missing.push('proposal'); }
if (missing.length > 0) {
  return stop('hermes_contract_incomplete:' + missing.join(','));
}
if (a.source_run_key !== x.run_key || a.source_run_id !== x.run_id) {
  return stop('analysis_source_run_mismatch');
}
if (a.period_basis !== 'IS' || x.period_basis !== 'IS') {
  return stop('period_basis_not_is');
}
if (x.round_index === 0) {
  // The baseline has no previous hypothesis.
  if (a.previous_hypothesis_ref !== null && a.previous_hypothesis_ref !== undefined) {
    return stop('baseline_has_prior_hypothesis');
  }
} else {
  if (!isText(a.previous_hypothesis_ref)) {
    return stop('missing_prior_hypothesis');
  }
  if (a.previous_hypothesis_ref !== x.prior_hypothesis_ref) {
    return stop('prior_hypothesis_ref_mismatch');
  }
}
return [{ json: Object.assign({}, x, { route: 'ANALYSIS_OK' }) }];

// Node07 is memory persistence only. The single Hermes turn did the
// read-before-write; this node is the deterministic ACK gate. It never reasons
// and it never rewrites the analysis.
const x = $input.first().json;
if (x.route === 'NEEDS_REVIEW') { return [{ json: x }]; }
const a = x.analysis || {};
const ack = x.wiki_ack;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (!ack || typeof ack !== 'object' || Array.isArray(ack)) { return stop('wiki_ack_missing'); }
if (ack.status === 'CONFLICT') { return stop('wiki_ack_conflict_no_overwrite'); }
if (ack.status !== 'ACK') { return stop('wiki_ack_' + String(ack.status)); }
const noteRef = 'quant/research-loop/' + x.run_key + '.md';
if (ack.note_ref !== noteRef) { return stop('wiki_note_ref_not_canonical'); }
if (ack.run_key !== x.run_key) { return stop('wiki_ack_run_key_mismatch'); }
if (typeof ack.analysis_hash !== 'string' || !/^[a-f0-9]{64}$/.test(ack.analysis_hash)) { return stop('wiki_ack_hash_bad_shape'); }
if (ack.analysis_hash !== a.analysis_hash) { return stop('wiki_ack_analysis_hash_mismatch'); }
return [{ json: Object.assign({}, x, { route: 'WIKI_PERSISTED' }) }];

// Node08 is deterministic validation only. No LLM runs here.
// No second opinion, no model review layer.
const x = $input.first().json;
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (x.route === 'NEEDS_REVIEW') {
  return [{ json: x }];
}
const a = x.analysis;
const ack = x.wiki_ack;
if (!ack || typeof ack !== 'object') { return stop('wiki_ack_missing'); }
if (ack.status !== 'ACK') { return stop('wiki_ack_' + ack.status); }
if (ack.run_key !== x.run_key) { return stop('wiki_ack_run_key_mismatch'); }
if (ack.analysis_hash !== a.analysis_hash) { return stop('analysis_hash_mismatch'); }
if (typeof ack.note_ref !== 'string' || ack.note_ref.length === 0) { return stop('wiki_note_ref_missing'); }
if (x.period_basis !== 'IS' || a.period_basis !== 'IS') { return stop('period_basis_not_is'); }
if (!a.proposal || a.proposal.source_run_key !== x.run_key) { return stop('proposal_source_run_mismatch'); }

// The IS-only allowlist is the primary OOS gate. A key outside the list is
// unexpected material.
const allowedTop = [
  'analysis_ref', 'analysis_hash', 'expectation_vs_actual', 'lessons',
  'period_basis', 'previous_hypothesis_ref', 'proposal', 'source_run_id',
  'source_run_key', 'worth_retesting'
];
const topKeys = Object.keys(a);
for (const key of topKeys) {
  if (allowedTop.indexOf(key) === -1) { return stop('unexpected_analysis_field:' + key); }
}
// A conservative regex is the second line of defence.
if (/(^|[^a-z])(oos|holdout|out_of_sample|out-of-sample)([^a-z]|$)/i.test(JSON.stringify(a))) {
  return stop('oos_material_in_analysis');
}
// The Wiki note holds lessons and references only. It must not copy raw orders.
const rawKeys = [];
const walk = (node) => {
  if (Array.isArray(node)) {
    node.forEach(walk);
    return;
  }
  if (node && typeof node === 'object') {
    Object.keys(node).forEach((key) => {
      rawKeys.push(key);
      walk(node[key]);
    });
  }
};
walk(a);
const rawHit = rawKeys.filter((key) => /(trades|equity|orders|fills|positions)/i.test(key));
if (rawHit.length > 0) { return stop('raw_result_material:' + rawHit.join(',')); }

// One change set only. Each parameter must be allowed upstream.
let changeSet = null;
if (a.worth_retesting === true) {
  const candidate = a.proposal.change_set;
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
    return stop('change_set_must_be_one_group');
  }
  if (a.proposal.change_sets !== undefined) { return stop('multiple_change_sets'); }
  if (candidate.hypothesis_groups !== undefined) { return stop('multiple_change_groups'); }
  const params = candidate.params;
  if (!params || typeof params !== 'object' || Array.isArray(params) || Object.keys(params).length === 0) {
